// Browser acceptance for the remaining teacher workflow:
// login -> open a persisted lesson -> edit -> save -> reload -> export files.
// Uses an existing test account generated by the Autopilot acceptance run and
// the isolated local database. No production account or data is involved.
const { chromium } = require('playwright')
const fs = require('fs')
const path = require('path')

const WEB = (process.env.TF_WEB_URL || 'http://localhost:3100').replace(/\/$/, '')
const API = (process.env.TF_API_URL || 'http://localhost:8000').replace(/\/$/, '')
const EMAIL = process.env.TF_TEACHER_EMAIL || ''
const PASSWORD = process.env.TF_TEACHER_PASSWORD || ''
const OUT = path.join(__dirname, '..', '..', 'backend', 'temp', 'e2e-exports')
fs.mkdirSync(OUT, { recursive: true })

let pass = 0, fail = 0
function log(ok, label, detail) {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`)
  if (ok) pass++; else fail++
}

async function login(page) {
  await page.goto(`${WEB}/login`, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.getByText('Welcome back, teacher.').waitFor({ timeout: 30000 })
  await page.locator('input[type="email"]').fill(EMAIL)
  await page.locator('input[type="password"]').fill(PASSWORD)
  await page.getByRole('button', { name: 'Sign In' }).click()
  await page.waitForURL(/\/dashboard/, { timeout: 30000 })
  await page.waitForLoadState('networkidle').catch(() => {})
}

async function apiGet(page, p) {
  return page.evaluate(async ({ apiBase, p }) => {
    const token = sessionStorage.getItem('teachflow_token')
    const res = await fetch(`${apiBase}${p}`, {
      headers: token ? { Authorization: `Bearer ${token}` } : {},
    })
    let body = null
    try { body = await res.json() } catch { /* non-JSON */ }
    return { status: res.status, body }
  }, { apiBase: API, p })
}

async function download(page, label, name, action) {
  const [dl] = await Promise.all([
    page.waitForEvent('download', { timeout: 180000 }),
    action(),
  ])
  const target = path.join(OUT, name)
  await dl.saveAs(target)
  const bytes = fs.readFileSync(target)
  log(true, `${label}: browser saved a file`, `${bytes.length} bytes`)
  return { target, bytes }
}

;(async () => {
  if (!EMAIL || !PASSWORD) {
    console.error('Set TF_TEACHER_EMAIL and TF_TEACHER_PASSWORD to a local acceptance account.')
    process.exit(2)
  }
  const browser = await chromium.launch({ headless: true })
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, acceptDownloads: true })
  const page = await ctx.newPage()
  const pageErrors = []
  const httpErrors = []
  page.on('pageerror', (e) => pageErrors.push(String(e)))
  page.on('response', (r) => {
    if (r.status() >= 400) httpErrors.push(`${r.status()} ${r.url().replace(WEB, '').slice(0, 120)}`)
  })

  try {
    await login(page)
    log(true, 'teacher login succeeds', EMAIL)

    const all = await apiGet(page, '/api/generation/lessons')
    const lessons = all.body?.lesson_plans || []
    log(all.status === 200 && lessons.length > 0, 'persisted lessons are available through the API',
      `count=${lessons.length}`)
    const lesson = lessons[0]
    const lessonId = lesson.id
    const schemeId = lesson.scheme_id
    log(Boolean(lessonId && schemeId), 'lesson carries stable lesson + scheme ids',
      `${lessonId} / ${schemeId}`)

    const originalTopic = lesson.lesson_topic || ''
    // Deliberately not an epoch stamp: the persistence boundary strips
    // internal/test epoch suffixes from teacher-visible text.
    const stamp = 'browserreview'
    const topic = `E2E input devices ${stamp}`
    const intro = `Teacher E2E check ${stamp}: identify manual and automatic input devices and give one example of each.`

    await page.goto(`${WEB}/lessons/${lessonId}`, { waitUntil: 'domcontentloaded', timeout: 60000 })
    await page.locator('#lesson-topic').waitFor({ timeout: 60000 })
    log(await page.locator('#lesson-topic').inputValue() === originalTopic,
      'lesson detail page opens the persisted lesson', originalTopic.slice(0, 60))

    await page.locator('#lesson-topic').fill(topic)
    await page.locator('#lesson-introduction').fill(intro)
    await page.getByRole('button', { name: /save changes/i }).click()
    await page.getByText('Saved', { exact: false }).first().waitFor({ timeout: 30000 })
    log(true, 'Save Changes reports success')

    const savedApi = await apiGet(page, `/api/generation/lessons/${lessonId}`)
    log(savedApi.body?.lesson_topic === topic, 'API returns the edited topic', savedApi.body?.lesson_topic)
    log(savedApi.body?.introduction === intro, 'API returns the edited starter')

    await page.reload({ waitUntil: 'domcontentloaded', timeout: 60000 })
    await page.locator('#lesson-topic').waitFor({ timeout: 60000 })
    const reloadedTopic = await page.locator('#lesson-topic').inputValue()
    const reloadedIntro = await page.locator('#lesson-introduction').inputValue()
    log(reloadedTopic === topic, 'edited topic survives reload', reloadedTopic)
    log(reloadedIntro === intro, 'edited starter survives reload')

    await page.goto(`${WEB}/generate/${schemeId}`, { waitUntil: 'domcontentloaded', timeout: 60000 })
    await page.locator('[data-lesson-workspace]').waitFor({ timeout: 120000 })
    await page.getByRole('button', { name: /download docx/i }).first().waitFor({ timeout: 60000 })
    log(true, 'export controls render on the generate page')

    const docx = await download(page, 'DOCX', `lesson-${stamp}.docx`, () =>
      page.getByRole('button', { name: /download docx/i }).first().click())
    log(docx.bytes.slice(0, 2).toString() === 'PK' && docx.bytes.length > 10000,
      'DOCX is a real package', `${docx.bytes.length} bytes`)

    const pdf = await download(page, 'PDF', `lesson-${stamp}.pdf`, () =>
      page.getByRole('button', { name: /download pdf/i }).first().click())
    log(pdf.bytes.slice(0, 5).toString() === '%PDF-' && pdf.bytes.length > 3000,
      'PDF has the PDF signature', `${pdf.bytes.length} bytes`)

    const xlsx = await download(page, 'XLSX', `lesson-${stamp}.xlsx`, () =>
      page.getByRole('button', { name: /download register/i }).first().click())
    log(xlsx.bytes.slice(0, 2).toString() === 'PK' && xlsx.bytes.length > 3000,
      'XLSX is a real package', `${xlsx.bytes.length} bytes`)

    let zip = null
    if (process.env.TF_EXPECT_ZIP === '1') {
      zip = await download(page, 'ZIP', `lessons-${stamp}.zip`, () =>
        page.getByRole('button', { name: /export zip/i }).first().click())
      log(zip.bytes.slice(0, 2).toString() === 'PK' && zip.bytes.length > 10000,
        'ZIP is a real archive', `${zip.bytes.length} bytes`)
    } else {
      log(true, 'ZIP export deferred to the Pro entitlement run',
        'TF_EXPECT_ZIP!=1')
    }

    log(pageErrors.length === 0, 'no uncaught page errors', pageErrors.slice(0, 2).join(' | '))
    log(httpErrors.length === 0, 'no HTTP 4xx/5xx during the journey', httpErrors.slice(0, 3).join(' | '))
    fs.writeFileSync(path.join(OUT, 'export-paths.json'), JSON.stringify({
      docx: docx.target, pdf: pdf.target, xlsx: xlsx.target,
      zip: zip ? zip.target : null,
      lessonId, schemeId, topic, intro,
    }, null, 2))
  } catch (e) {
    log(false, 'journey completed', e.message.split('\n')[0].slice(0, 220))
    await page.screenshot({ path: path.join(OUT, '99-failure.png'), fullPage: false }).catch(() => {})
  } finally {
    await browser.close()
  }

  console.log(`\n${pass} passed, ${fail} failed — exports in ${OUT}`)
  process.exit(fail ? 1 : 0)
})()
